class PropScan:
    """Main scanner class - Optimized version."""

    def __init__(self):
        self.managers = [
            FlatpakManager(),
            PacmanManager(),
            AptManager(),
            DnfManager(),
        ]
        self.detector = LicenseBasedDetector()

    def get_available_managers(self) -> List[PackageManager]:
        """Get list of available package managers."""
        return [manager for manager in self.managers if manager.is_available()]

    def scan_manager(self, manager: PackageManager) -> List[Dict[str, any]]:
        """Scan a specific package manager for proprietary software."""
        packages = manager.get_installed_packages()
        proprietary = []

        # Process packages concurrently for proprietary detection
        max_workers = min(32, len(packages)) if packages else 1

        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            # Submit all detection tasks
            future_to_package = {
                executor.submit(self._check_package_proprietary, package): package
                for package in packages
            }

            # Collect results as they complete
            for future in as_completed(future_to_package):
                package = future_to_package[future]
                try:
                    is_proprietary, detection_reason = future.result()
                    if is_proprietary:
                        package["detection_reason"] = detection_reason
                        proprietary.append(package)
                except Exception as e:
                    # If detection fails, skip the package
                    continue

        return proprietary

    def _check_package_proprietary(self, package: Dict[str, any]) -> Tuple[bool, str]:
        """Check if a package is proprietary and return detection reason."""
        is_proprietary = self.detector.is_proprietary(package)
        detection_reason = self.detector.get_detection_reason(package)
        return is_proprietary, detection_reason

    def scan_all(self, manager_filter: Optional[str] = None) -> Dict[str, List[Dict[str, any]]]:
        """Scan all available package managers concurrently."""
        available_managers = self.get_available_managers()

        # Filter managers if specified
        if manager_filter:
            available_managers = [
                manager for manager in available_managers 
                if manager.name.lower() == manager_filter.lower()
            ]

        if not available_managers:
            return {}

        results = {}

        # Scan all managers concurrently
        with ThreadPoolExecutor(max_workers=len(available_managers)) as executor:
            # Submit all manager scan tasks
            future_to_manager = {
                executor.submit(self.scan_manager, manager): manager
                for manager in available_managers
            }

            # Collect results as they complete
            for future in as_completed(future_to_manager):
                manager = future_to_manager[future]
                try:
                    proprietary = future.result()
                    if proprietary:
                        results[manager.name] = proprietary
                except Exception as e:
                    # If manager scan fails, continue with others
                    continue

        return results
